// Join-site guest app: refuse to run inside a frame (GitHub Pages cannot send frame-ancestors, and a <meta> CSP
// ignores that directive). A classic script, first in <head>: blank the page before anything else loads. (Generated by
// scripts/build-join-site-app.js.)
(function () {
  try {
    if (window.top === window.self) return;
  } catch (_) {
    /* a cross-origin top throws: that means we are framed */
  }
  document.documentElement.hidden = true;
  try {
    window.top.location = window.self.location.href;
  } catch (_) {
    /* sandboxed: the page stays hidden */
  }
  throw new Error("framed");
})();
